import{_ as t,o,c as a,ao as d}from"./chunks/framework.ucUddl5u.js";const u=JSON.parse('{"title":"Writing a Mode Plugin","description":"","frontmatter":{},"headers":[],"relativePath":"extend/mode.md","filePath":"extend/mode.md","lastUpdated":null}'),r={name:"extend/mode.md"};function i(s,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="Writing-a-Mode-Plugin" tabindex="-1">Writing a Mode Plugin <a class="header-anchor" href="#Writing-a-Mode-Plugin" aria-label="Permalink to &quot;Writing a Mode Plugin {#Writing-a-Mode-Plugin}&quot;">​</a></h1><p>A <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.Mode"><code>Mode</code></a> is a switchable root for the collapsible nav tree. Files, Modules, Sessions, and Hosts are modes; a hotkey swaps which mode&#39;s tree fills the navigation pane, and cursor position is preserved per mode across switches. A mode plugin supplies a new such root.</p><p>This page documents the mode contract. For the conceptual overview see <a href="./abi">The Dispatch ABI</a>; for the symbol reference see <a href="./../ref/api-core">API — ConceptExplorerCore</a>.</p><div class="tip custom-block"><p class="custom-block-title">Status: modes are built into the frontend and backend today</p><p>The mode contract is part of the ABI, but in phase 1 the core modes are implemented in the Rust frontend and backend, not in plugin packages. The packages under <code>julia/plugins/</code> are all <code>FileType</code> plugins (Julia source, Markdown, JSON, plain text, PDF, video) — there is <strong>no</strong> mode-plugin package in the tree yet. This page describes the contract a third-party mode would dispatch on and the shape core&#39;s own modes follow; it does not point at a <code>modes-mode</code> package, because none exists. The narrowest extension surface that is fully plugin-shaped today is the <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.FileType"><code>FileType</code></a> — see <a href="./filetype">Writing a FileType Plugin</a>.</p></div><h2 id="The-Mode-contract" tabindex="-1">The Mode contract <a class="header-anchor" href="#The-Mode-contract" aria-label="Permalink to &quot;The Mode contract {#The-Mode-contract}&quot;">​</a></h2><p>A mode is a singleton subtype of <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.Mode"><code>Mode</code></a> plus three dispatched methods. The same three-column shape applies to every mode; the methods supply the tree and its previews:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Method</th><th style="text-align:right;">Returns</th><th style="text-align:right;">Role</th></tr></thead><tbody><tr><td style="text-align:right;"><code>tree_root(::Type{M}, project)</code></td><td style="text-align:right;"><a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.TreeNode"><code>TreeNode</code></a></td><td style="text-align:right;">the mode&#39;s root node for <code>project</code></td></tr><tr><td style="text-align:right;"><code>tree_children(::Type{M}, node)</code></td><td style="text-align:right;"><code>Vector{</code><a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.TreeNode"><code>TreeNode</code></a><code>}</code></td><td style="text-align:right;">children of a node (lazy column fill)</td></tr><tr><td style="text-align:right;"><code>preview_for(::Type{M}, node)</code></td><td style="text-align:right;"><a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.PreviewPayload"><code>PreviewPayload</code></a></td><td style="text-align:right;">preview for the selected node</td></tr></tbody></table><p>These mirror the <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.FileType"><code>FileType</code></a> methods (<a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.matches"><code>matches</code></a> / <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.preview"><code>preview</code></a> / <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.parse_entities"><code>parse_entities</code></a>) in style: a small set of generic functions, one method per mode. As <a href="./abi">the ABI page</a> notes, core does not ship the generic <code>tree_root</code> / <code>tree_children</code> / <code>preview_for</code> stubs in phase 1 — they are dispatched the same way and implemented by the modes layered above core.</p><h2 id="The-tree-IR" tabindex="-1">The tree IR <a class="header-anchor" href="#The-tree-IR" aria-label="Permalink to &quot;The tree IR {#The-tree-IR}&quot;">​</a></h2><p>Both mode outputs cross the Rust↔Julia boundary as opaque-payload structs, so the frontend renders any mode without learning its internals:</p><ul><li><p><a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.TreeNode"><code>TreeNode</code></a> — one node of a column. Fields: <code>id</code> (opaque to Rust), <code>label</code>, <code>kind</code> (a <code>Symbol</code> like <code>:module</code>, <code>:function</code>, <code>:pngfile</code>), <code>has_children</code>, <code>badges</code> (a <code>Vector{Symbol}</code> for the cross-cutting color layer, e.g. <code>:stale</code>, <code>:user_edited</code>, <code>:immutable</code>), and a kind-defined <code>payload::Dict{String,Any}</code> the frontend never inspects. The convenience constructor is <code>TreeNode(id, label, kind; has_children=false, badges=Symbol[], payload=Dict())</code>.</p></li><li><p><a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.PreviewPayload"><code>PreviewPayload</code></a> — the rendered preview for a node: <code>mime</code>, <code>data</code> bytes, and an <code>extras</code> dictionary. The frontend dispatches on <code>mime</code> to pick a renderer, exactly as it does for file previews.</p></li></ul><p>Because the payloads are opaque, <strong>adding a <code>Mode</code> requires zero Rust changes</strong> — the frontend draws whatever tree the kernel sends and renders whatever the preview&#39;s MIME names.</p><h2 id="How-a-third-party-mode-would-dispatch" tabindex="-1">How a third-party mode would dispatch <a class="header-anchor" href="#How-a-third-party-mode-would-dispatch" aria-label="Permalink to &quot;How a third-party mode would dispatch {#How-a-third-party-mode-would-dispatch}&quot;">​</a></h2><p>The contract is symmetrical with the FileType case. A mode package would:</p><ol><li><p>Depend on <code>ConceptExplorerCore</code> and <code>using</code> it.</p></li><li><p>Declare a singleton subtype: <code>struct MyMode &lt;: ConceptExplorerCore.Mode end</code>.</p></li><li><p>Implement <code>tree_root</code> to build the root <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.TreeNode"><code>TreeNode</code></a> from the project, setting <code>kind</code>, <code>has_children</code>, and any color-layer <code>badges</code>.</p></li><li><p>Implement <code>tree_children</code> to expand a node into the next column&#39;s nodes, reading the parent node&#39;s <code>payload</code> to know what to enumerate.</p></li><li><p>Implement <code>preview_for</code> to return a <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.PreviewPayload"><code>PreviewPayload</code></a> for the selected node, choosing a MIME the frontend renders (see the MIME table in <a href="./filetype">Writing a FileType Plugin</a>).</p></li></ol><p>Discovery would follow the same explicit model as FileType plugins: the package is listed in the project&#39;s <code>[sot].extensions</code> and <code>Base.require</code>d at kernel startup — see <a href="./discovery">Discovery &amp; Configuration</a>.</p><h2 id="The-current-core-modes" tabindex="-1">The current core modes <a class="header-anchor" href="#The-current-core-modes" aria-label="Permalink to &quot;The current core modes {#The-current-core-modes}&quot;">​</a></h2><p>For reference, the modes the kernel hosts today (the ones a hotkey switches between in the running app):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Mode</th><th style="text-align:right;">Column 1 → 2 → 3</th><th style="text-align:right;">Preview</th></tr></thead><tbody><tr><td style="text-align:right;">Files</td><td style="text-align:right;">parent dir → current dir → contents</td><td style="text-align:right;">file at appropriate fidelity</td></tr><tr><td style="text-align:right;">Modules (read-only)</td><td style="text-align:right;">modules → definitions (types, functions, macros, submodules)</td><td style="text-align:right;">method source + concept artifact</td></tr><tr><td style="text-align:right;">Sessions</td><td style="text-align:right;">workspaces → timeline → detail</td><td style="text-align:right;">session detail</td></tr><tr><td style="text-align:right;">Hosts</td><td style="text-align:right;">configured hosts → endpoint detail</td><td style="text-align:right;">host endpoint summary</td></tr></tbody></table><p>Types, Math, and Outputs modes are designed but not yet built; Agents mode is pinned for later (single orchestrator only in phase 1). The mode table in the <a href="./../">root design overview</a> and <code>CLAUDE.md</code> lists the full intended set.</p><h2 id="Why-modes-aren&#39;t-packaged-yet" tabindex="-1">Why modes aren&#39;t packaged yet <a class="header-anchor" href="#Why-modes-aren&#39;t-packaged-yet" aria-label="Permalink to &quot;Why modes aren&#39;t packaged yet {#Why-modes-aren&#39;t-packaged-yet}&quot;">​</a></h2><p>Extracting a mode into a standalone package is deferred, not blocked: the contract above is exactly what such a package would implement. Until the generic stubs and a third-party mode example exist, treat this page as the design of the mode seam and use the <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.FileType"><code>FileType</code></a> path for a plugin you can ship today.</p><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><p><a href="./abi">The Dispatch ABI</a> — the conceptual contract and the serialization seam.</p></li><li><p><a href="./filetype">Writing a FileType Plugin</a> — the fully plugin-shaped surface today.</p></li><li><p><a href="./../ref/api-core">API — ConceptExplorerCore</a> — <code>Mode</code>, <code>TreeNode</code>, <code>PreviewPayload</code>.</p></li></ul>',24)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
